mapper.insert:
MERGE INTO MST_EXCHARGE_QUOTE L USING (
select #{item.exchargeCode, jdbcType=VARCHAR } EXCHARGE_CODE, #{item.tradeDate ,jdbcType=DATE } TRADE_DATE, #{item.datasourceType ,jdbcType=VARCHAR } DATASOURCE_TYPE, #{item.openPrice ,jdbcType=DECIMAL } OPEN_PRICE, #{item.closePrice ,jdbcType=DECIMAL } CLOSE_PRICE, #{item.highPrice ,jdbcType=DECIMAL } HIGH_PRICE, #{item.lowPrice ,jdbcType=DECIMAL } LOW_PRICE, #{item.midPrice ,jdbcType=DECIMAL } MID_PRICE, #{item.basisCyy ,jdbcType=VARCHAR } BASIS_CYY, #{item.quotCyy ,jdbcType=VARCHAR } QUOT_CYY, #{item.quotUnit ,jdbcType=DECIMAL } QUOT_UNIT, #{item.inputType ,jdbcType=VARCHAR } INPUT_TYPE, #{item.createUser ,jdbcType=VARCHAR } CREATE_USER, #{item.createDept ,jdbcType=VARCHAR } CREATE_DEPT, #{item.createTime ,jdbcType=TIMESTAMP } CREATE_TIME, #{item.updateUser ,jdbcType=VARCHAR } UPDATE_USER, #{item.updateTime ,jdbcType=TIMESTAMP } UPDATE_TIME from dual
) TEMP ON (L.TRADE_DATE = TEMP.TRADE_DATE) WHEN MATCHED THEN UPDATE SET L.EXCHARGE_CODE = TEMP.EXCHARGE_CODE, L.TRADE_DATE = TEMP.TRADE_DATE, L.DATASOURCE_TYPE = TEMP.DATASOURCE_TYPE, L.OPEN_PRICE = TEMP.OPEN_PRICE, L.CLOSE_PRICE = TEMP.CLOSE_PRICE, L.HIGH_PRICE = TEMP.HIGH_PRICE, L.LOW_PRICE = TEMP.LOW_PRICE, L.MID_PRICE = TEMP.MID_PRICE, L.BASIS_CYY = TEMP.BASIS_CYY, L.QUOT_CYY = TEMP.QUOT_CYY, L.QUOT_UNIT = TEMP.QUOT_UNIT, L.INPUT_TYPE = TEMP.INPUT_TYPE, L.CREATE_USER = TEMP.CREATE_USER, L.CREATE_DEPT = TEMP.CREATE_DEPT, L.CREATE_TIME = TEMP.CREATE_TIME, L.UPDATE_USER = TEMP.UPDATE_USER, L.UPDATE_TIME = TEMP.UPDATE_TIME WHEN NOT MATCHED THEN INSERT ( EXCHARGE_CODE, TRADE_DATE, DATASOURCE_TYPE, OPEN_PRICE, CLOSE_PRICE, HIGH_PRICE, LOW_PRICE, MID_PRICE, BASIS_CYY, QUOT_CYY, QUOT_UNIT, INPUT_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) VALUES( TEMP.EXCHARGE_CODE, TEMP.TRADE_DATE, TEMP.DATASOURCE_TYPE, TEMP.OPEN_PRICE, TEMP.CLOSE_PRICE, TEMP.HIGH_PRICE, TEMP.LOW_PRICE, TEMP.MID_PRICE, TEMP.BASIS_CYY, TEMP.QUOT_CYY, TEMP.QUOT_UNIT, TEMP.INPUT_TYPE, TEMP.CREATE_USER, TEMP.CREATE_DEPT, TEMP.CREATE_TIME, TEMP.UPDATE_USER, TEMP.UPDATE_TIME )
